const { spawn } = require("child_process");
const http = require("http");

async function runSmokeTest() {
  console.log("[SmokeTest] Starting production server on port 3456...");
  const serverProc = spawn("node", ["server/dist/index.js"], {
    env: { ...process.env, PORT: "3456", NODE_ENV: "production" },
    stdio: ["pipe", "pipe", "pipe"],
  });

  serverProc.stdout.on("data", (d) => process.stdout.write(`[SERVER OUT] ${d}`));
  serverProc.stderr.on("data", (d) => process.stderr.write(`[SERVER ERR] ${d}`));

  // Wait for server to start
  await new Promise((resolve) => setTimeout(resolve, 2500));

  function get(url) {
    return new Promise((resolve, reject) => {
      http.get(`http://localhost:3456${url}`, (res) => {
        let body = "";
        res.on("data", (c) => (body += c));
        res.on("end", () => resolve({ status: res.statusCode, headers: res.headers, body }));
      }).on("error", reject);
    });
  }

  try {
    // 1. Healthz readiness
    console.log("[SmokeTest] 1. Checking GET /healthz");
    const h1 = await get("/healthz");
    console.log(`Status: ${h1.status}, Content-Type: ${h1.headers["content-type"]}`);
    const h1Json = JSON.parse(h1.body);
    console.log(`Payload: status=${h1Json.status}, mode=${h1Json.mode}, checks=${JSON.stringify(h1Json.checks)}`);

    // 2. Healthz liveness
    console.log("\n[SmokeTest] 2. Checking GET /healthz/live");
    const h2 = await get("/healthz/live");
    console.log(`Status: ${h2.status}, Payload: ${h2.body}`);

    // 3. API Accounts demo
    console.log("\n[SmokeTest] 3. Checking GET /api/accounts?demo=true");
    const acc = await get("/api/accounts?demo=true");
    console.log(`Status: ${acc.status}`);
    const accJson = JSON.parse(acc.body);
    console.log(`Accounts returned: ${accJson.data.length}, total: ${accJson.pagination.total}, synthetic: ${accJson.meta.synthetic}`);

    // 4. Root HTML
    console.log("\n[SmokeTest] 4. Checking GET / (Vite production bundle)");
    const root = await get("/");
    console.log(`Status: ${root.status}, Content-Type: ${root.headers["content-type"]}`);
    console.log(`Contains root div: ${root.body.includes('<div id="root">')}`);

    // 5. SPA Fallback
    console.log("\n[SmokeTest] 5. Checking GET /investigations/new (SPA fallback)");
    const spa = await get("/investigations/new");
    console.log(`Status: ${spa.status}, Content-Type: ${spa.headers["content-type"]}`);
    console.log(`Contains root div: ${spa.body.includes('<div id="root">')}`);

    // 6. API 404
    console.log("\n[SmokeTest] 6. Checking GET /api/nonexistent (API 404 JSON)");
    const notFound = await get("/api/nonexistent");
    console.log(`Status: ${notFound.status}, Content-Type: ${notFound.headers["content-type"]}`);
    console.log(`Body: ${notFound.body}`);

    console.log("\n[SmokeTest] ALL 6 CHECKS PASSED SUCCESSFULLY!");
  } finally {
    serverProc.kill();
  }
}

runSmokeTest().catch((err) => {
  console.error("Smoke test failed:", err);
  process.exit(1);
});

